using System;using System.Linq;using System.Text;using System.Text.RegularExpressions;using System.Globalization;using System.Collections.Generic;
namespace BeamScheduleFormatter {
// Reads STAAD.Pro geometry and node displacement data from pasted/exported tables, .STD input files and .ANL output files.
static class StaadDisplacements {
 internal static readonly string[] Units={"m","mm","cm","in","ft"};
 internal static double Unit(string unit){switch((unit??"").Trim().ToLowerInvariant()){case "m":return 1;case "mm":return .001;case "cm":return .01;case "in":return .0254;case "ft":return .3048;default:throw new Exception("Select an explicit length unit (m, mm, cm, in or ft).");}}
 internal static double Number(string value){double result;string text=(value??"").Trim().Replace('D','E').Replace('d','E');if(!double.TryParse(text,NumberStyles.Float,CultureInfo.InvariantCulture,out result)||double.IsNaN(result)||double.IsInfinity(result))throw new Exception("Invalid number '"+value+"'. Use a decimal point without thousands separators.");return result;}
 static bool IsNumber(string value){double result;return double.TryParse((value??"").Trim().Replace('D','E').Replace('d','E'),NumberStyles.Float,CultureInfo.InvariantCulture,out result);}
 internal static int Id(string text){int result;if(!int.TryParse((text??"").Trim(),NumberStyles.Integer,CultureInfo.InvariantCulture,out result)||result<=0)throw new Exception("Invalid STAAD node/member number '"+text+"'.");return result;}
 // Detects a length unit written in a header or STAAD UNIT statement. STAAD writes millimetres as MMS.
 internal static string DetectUnit(string text){string t=(text??"").ToUpperInvariant();if(Regex.IsMatch(t,@"MILLIMET|\bMMS?\b"))return "mm";if(Regex.IsMatch(t,@"CENTIMET|\bCMS?\b"))return "cm";if(Regex.IsMatch(t,@"\bINCH(?:ES)?\b|\bINS?\b"))return "in";if(Regex.IsMatch(t,@"\bFEET\b|\bFOOT\b|\bFT\b|\bFEE\b"))return "ft";if(Regex.IsMatch(t,@"\bMET(?:ER|RE)S?\b|\bMTR\b|\bM\b"))return "m";return null;}
 internal static string[] Fields(string line){char separator=line.Contains("\t")?'\t':line.Contains(",")?',':' ';if(separator==' ')return Regex.Split(line.Trim(),@"\s+");var values=new List<string>();var field=new StringBuilder();bool quote=false;for(int i=0;i<line.Length;i++){char c=line[i];if(c=='"'){if(quote&&i+1<line.Length&&line[i+1]=='"'){field.Append('"');i++;}else quote=!quote;}else if(c==separator&&!quote){values.Add(field.ToString().Trim());field.Length=0;}else field.Append(c);}if(quote)throw new Exception("Unclosed CSV quote.");values.Add(field.ToString().Trim());return values.ToArray();}
 static string Key(string text){return Regex.Replace((text??"").ToLowerInvariant(),@"[\s_\-\.]+","");}
 static string Bare(string text){return Regex.Replace(Key(text),@"\(.*\)|\[.*\]","");}
 static bool Axis(string header,string axis){string k=Bare(header);string full=Key(header);if(k.StartsWith("r")&&k.Length>1&&k[1]==axis[0])return false;if(full.Contains("rad")||full.Contains("rot"))return false;return k==axis||Units.Any(u=>k==axis+u)||k==axis+"coord"||k==axis+"coordinate"||k=="global"+axis||k=="d"+axis||k==axis+"trans"||k==axis+"translation"||k==axis+"displacement"||k==axis+"disp";}
 static readonly string[] NodeKeys={"node","nodeid","joint","nodeno","jointno"},CaseKeys={"l/c","lc","case","loadcase","load","loadcombination"},MemberKeys={"member","beam","memberid","memb","beamno","memberno"},StartKeys={"start","startnode","nodea","node1","jointi","nodei","inode"},EndKeys={"end","endnode","nodeb","node2","jointj","nodej","jnode"};
 static int Find(string[] header,string[] keys){return Array.FindIndex(header,h=>keys.Contains(Bare(h))||keys.Contains(Key(h)));}
 internal static List<string[]> Rows(string text){return (text??"").Replace("\r","").Split('\n').Where(line=>!string.IsNullOrWhiteSpace(line)).Select(Fields).ToList();}
 internal static void AddNode(BeamDeflectionData data,BeamNode node){BeamNode old;if(data.Nodes.TryGetValue(node.Id,out old)){if(BeamDeflection.Distance(old,node)>1e-8)throw new Exception("Conflicting coordinates for node "+node.Id+".");return;}data.Nodes.Add(node.Id,node);}
 internal static void AddMember(BeamDeflectionData data,BeamMember member){BeamMember old;if(data.Members.TryGetValue(member.Id,out old)){if(!(old.A==member.A&&old.B==member.B||old.A==member.B&&old.B==member.A))throw new Exception("Conflicting incidences for member "+member.Id+".");return;}data.Members.Add(member.Id,member);}
 internal static void AddDisplacement(BeamDeflectionData data,BeamDisplacement row){var old=data.Displacements.FirstOrDefault(d=>d.Node==row.Node&&d.Case.Equals(row.Case,StringComparison.OrdinalIgnoreCase));if(old!=null){if(Math.Abs(old.X-row.X)+Math.Abs(old.Y-row.Y)+Math.Abs(old.Z-row.Z)>1e-10)throw new Exception("Conflicting displacement for node "+row.Node+", load case "+row.Case+".");return;}data.Displacements.Add(row);}
 // Resolves one unit from the header cells; a header unit overrides the selected unit.
 static string HeaderUnit(string[] header,int[] columns,string selected,out string source){var found=columns.Where(c=>c>=0).Select(c=>DetectUnit(header[c])).Where(u=>u!=null).Distinct().ToList();if(found.Count>1)throw new Exception("The table headers mix different length units ("+string.Join(", ",found)+").");if(found.Count==1){source="table header ("+found[0]+")";return found[0];}Unit(selected);source="selected unit ("+selected+")";return selected;}
 internal static void Coordinates(BeamDeflectionData data,string text,string unit){var rows=Rows(text);int header=rows.FindIndex(r=>Find(r,NodeKeys)>=0&&r.Any(h=>Axis(h,"x"))&&r.Any(h=>Axis(h,"z")));if(header<0)throw new Exception("Node coordinate table needs Node, X, Y and Z column headers.");var names=rows[header];int id=Find(names,NodeKeys),x=Array.FindIndex(names,h=>Axis(h,"x")),y=Array.FindIndex(names,h=>Axis(h,"y")),z=Array.FindIndex(names,h=>Axis(h,"z"));if(y<0)throw new Exception("Node coordinate table is missing the Y column.");string source;string resolved=HeaderUnit(names,new[]{x,y,z},unit,out source);double factor=Unit(resolved);int count=0;
  for(int r=header+1;r<rows.Count;r++){var p=rows[r];if(p.Length<=new[]{id,x,y,z}.Max()){if(p.All(string.IsNullOrWhiteSpace))continue;throw new Exception("Incomplete node coordinate row "+(r+1)+".");}if(Bare(p[id])==Bare(names[id])||!IsNumber(p[id])&&DetectUnit(p[x])!=null)continue;AddNode(data,new BeamNode{Id=Id(p[id]),X=Number(p[x])*factor,Y=Number(p[y])*factor,Z=Number(p[z])*factor});count++;}
  if(count==0)throw new Exception("The node coordinate table has no data rows.");data.GeometryUnitSource=source;}
 internal static void Members(BeamDeflectionData data,string text){var rows=Rows(text);int header=rows.FindIndex(r=>Find(r,MemberKeys)>=0&&Find(r,StartKeys)>=0&&Find(r,EndKeys)>=0);if(header<0)throw new Exception("Member incidence table needs Member (or Beam), Node A and Node B column headers.");var names=rows[header];int id=Find(names,MemberKeys),a=Find(names,StartKeys),b=Find(names,EndKeys);int count=0;
  for(int r=header+1;r<rows.Count;r++){var p=rows[r];if(p.Length<=Math.Max(id,Math.Max(a,b))){if(p.All(string.IsNullOrWhiteSpace))continue;throw new Exception("Incomplete member incidence row "+(r+1)+".");}if(Bare(p[id])==Bare(names[id])||!IsNumber(p[id]))continue;AddMember(data,new BeamMember{Id=Id(p[id]),A=Id(p[a]),B=Id(p[b])});count++;}
  if(count==0)throw new Exception("The member incidence table has no data rows.");}
 internal static void Displacements(BeamDeflectionData data,string text,string unit){var rows=Rows(text);int header=rows.FindIndex(r=>Find(r,NodeKeys)>=0&&Find(r,CaseKeys)>=0);if(header<0)throw new Exception("Node displacement table needs Node, L/C and X, Y, Z translation column headers.");var names=rows[header];int id=Find(names,NodeKeys),lc=Find(names,CaseKeys),x=Array.FindIndex(names,h=>Axis(h,"x")),y=Array.FindIndex(names,h=>Axis(h,"y")),z=Array.FindIndex(names,h=>Axis(h,"z"));if(x<0||y<0||z<0)throw new Exception("Node displacement table needs X, Y and Z translation columns (rotations are not used).");
  // A separate unit row (for example: blank, blank, mm, mm, mm) may follow the header.
  int startRow=header+1;string[] unitRow=null;if(startRow<rows.Count&&rows[startRow].Length>z&&!IsNumber(rows[startRow][x])&&DetectUnit(rows[startRow][x])!=null){unitRow=rows[startRow];startRow++;}
  string source;string resolved=unitRow!=null?HeaderUnit(unitRow,new[]{x,y,z},unit,out source):HeaderUnit(names,new[]{x,y,z},unit,out source);double factor=Unit(resolved);string lastNode="",lastCase="";int count=0;
  for(int r=startRow;r<rows.Count;r++){var p=rows[r];if(p.Length<=new[]{id,lc,x,y,z}.Max()){if(p.All(string.IsNullOrWhiteSpace))continue;throw new Exception("Incomplete displacement row "+(r+1)+".");}if(Bare(p[id])==Bare(names[id]))continue;if(!IsNumber(p[x]))continue;string node=p[id]==""?lastNode:p[id],load=p[lc]==""?lastCase:p[lc];if(load=="")throw new Exception("Displacement row "+(r+1)+" has no load case.");if(node=="")throw new Exception("Displacement row "+(r+1)+" has no node.");AddDisplacement(data,new BeamDisplacement{Node=Id(node),Case=load,X=Number(p[x])*factor,Y=Number(p[y])*factor,Z=Number(p[z])*factor});lastNode=node;lastCase=load;count++;}
  if(count==0)throw new Exception("The node displacement table has no data rows.");data.DisplacementUnitSource=source;}
 static IEnumerable<int> NodeList(string text){var p=Regex.Split(text.Trim(),@"\s+");for(int i=0;i<p.Length;i++){int a;if(!int.TryParse(p[i],out a))yield break;if(i+2<p.Length&&p[i+1].Equals("TO",StringComparison.OrdinalIgnoreCase)){int b;if(!int.TryParse(p[i+2],out b))yield break;int step=1;if(i+4<p.Length&&p[i+3].Equals("BY",StringComparison.OrdinalIgnoreCase)&&int.TryParse(p[i+4],out step)&&step>0)i+=2;for(int n=a;n<=b;n+=step)yield return n;i+=2;}else yield return a;}}
 // Parses expanded JOINT COORDINATES / MEMBER INCIDENCES / SUPPORTS from a STAAD .STD file or the input echo in an .ANL file.
 internal static void Model(BeamDeflectionData data,string text,string defaultUnit,ISet<int> supports=null){string mode="";double factor=Unit(defaultUnit);string unitSource="selected unit ("+defaultUnit+")";string pending="";
  foreach(string raw in (text??"").Replace("\r","").Split('\n')){string line=Regex.Replace(raw,@"^\s*\d+\.\s+","").Trim();if(pending!=""){line=pending+" "+line;pending="";}if(line.EndsWith("-")){pending=line.Substring(0,line.Length-1);continue;}if(line==""||line.StartsWith("*"))continue;
   if(Regex.IsMatch(line,@"^SET\s+Z\s+UP",RegexOptions.IgnoreCase)){data.ZUp=true;continue;}
   if(Regex.IsMatch(line,@"^UNIT\b",RegexOptions.IgnoreCase)){string u=DetectUnit(Regex.Replace(line,@"\b(KNS?|KIPS?|NEWTONS?|N|KGS?|MTON|POUNDS?|LBS?|KG)\b","",RegexOptions.IgnoreCase));if(u!=null){factor=Unit(u);unitSource="STAAD UNIT command ("+u+")";}continue;}
   if(Regex.IsMatch(line,@"^JOINT\s+COORD",RegexOptions.IgnoreCase)){if(Regex.IsMatch(line,@"CYL",RegexOptions.IgnoreCase))throw new Exception("Cylindrical joint coordinates are not supported; export the Node table instead.");mode="nodes";line=Regex.Replace(line,@"^JOINT\s+COORD\w*","",RegexOptions.IgnoreCase).Trim();}
   else if(Regex.IsMatch(line,@"^MEMBER\s+INCI",RegexOptions.IgnoreCase)){mode="members";line=Regex.Replace(line,@"^MEMBER\s+INCI\w*","",RegexOptions.IgnoreCase).Trim();}
   else if(Regex.IsMatch(line,@"^SUPPORTS?\b",RegexOptions.IgnoreCase)){mode="supports";line=Regex.Replace(line,@"^SUPPORTS?","",RegexOptions.IgnoreCase).Trim();}
   else if(!Regex.IsMatch(line,@"^\d")){if((mode=="nodes"||mode=="members")&&Regex.IsMatch(line,@"^REPEAT",RegexOptions.IgnoreCase))throw new Exception("The model uses REPEAT generation. Export the expanded Node and Beam tables from STAAD instead.");mode="";continue;}
   if(mode==""||line=="")continue;
   foreach(string statement in line.Split(';')){string s=statement.Trim();if(s=="")continue;var p=Regex.Split(s,@"\s+");
    if(mode=="nodes"){if(p.Length!=4)throw new Exception("Unsupported joint statement '"+s+"'. Export the expanded Node table.");AddNode(data,new BeamNode{Id=Id(p[0]),X=Number(p[1])*factor,Y=Number(p[2])*factor,Z=Number(p[3])*factor});}
    else if(mode=="members"){if(p.Length!=3)throw new Exception("Unsupported member incidence statement '"+s+"'. Export the expanded Beam table.");AddMember(data,new BeamMember{Id=Id(p[0]),A=Id(p[1]),B=Id(p[2])});}
    else if(supports!=null){foreach(int n in NodeList(s))supports.Add(n);}}}
  if(data.Nodes.Count>0)data.GeometryUnitSource=unitSource;}
 // Reads JOINT DISPLACEMENT tables printed by STAAD (PRINT JOINT DISPLACEMENTS) and the echoed model when present.
 internal static void Anl(BeamDeflectionData data,string text,string geometryUnit,string displacementUnit){var model=new BeamDeflectionData();bool complete=true;try{Model(model,text,geometryUnit);}catch(Exception){complete=false;}
  if(complete&&model.Nodes.Count>0&&model.Members.Count>0){foreach(var node in model.Nodes.Values)AddNode(data,node);foreach(var member in model.Members.Values)AddMember(data,member);data.ZUp=model.ZUp;data.GeometryUnitSource=model.GeometryUnitSource+" in ANL input echo";}
  double factor=Unit(displacementUnit);string source="selected unit ("+displacementUnit+")";bool reading=false;int lastNode=0;int[] columns=null;int count=0;
  foreach(string line in (text??"").Replace("\r","").Split('\n')){
   if(Regex.IsMatch(line,@"^\s*\d+\.\s"))continue;
   if(Regex.IsMatch(line,@"(?:JOINT|NODE)\s+DISPLACEMENTS?\b",RegexOptions.IgnoreCase)&&!Regex.IsMatch(line,@"\bPRINT\b|MAXIMUM",RegexOptions.IgnoreCase)){reading=true;columns=null;lastNode=0;var m=Regex.Match(line,@"\(([^)]*)\)");string u=m.Success?DetectUnit(m.Groups[1].Value):null;if(u!=null){factor=Unit(u);source="ANL table heading ("+u+")";}continue;}
   if(!reading)continue;
   if(Regex.IsMatch(line,@"REACTION|MEMBER\s+(?:END\s+)?FORCE|MAXIMUM|SECTION\s+DISPL|STATIC\s+LOAD|\*\*\*\*|END\s+OF",RegexOptions.IgnoreCase)){reading=false;continue;}
   string[] p=Regex.Split(line.Trim(),@"\s+");
   if(Regex.IsMatch(line,@"JOINT\s+LOAD|NODE\s+L/C|NODE\s+LOAD",RegexOptions.IgnoreCase)){var head=p.Select(h=>h.ToUpperInvariant()).ToList();Func<string,int> col=name=>{int i=head.IndexOf(name);return i<0?-1:i-2;};columns=new[]{col("X-TRANS"),col("Y-TRANS"),col("Z-TRANS"),head.Count-2};if(columns[0]<0||columns[1]<0)throw new Exception("Unrecognized JOINT DISPLACEMENT column headings in the ANL file.");continue;}
   if(!p.All(IsNumber))continue;int values=columns!=null?columns[3]:p.Length>=7?6:3;int node,load,offset;
   if(p.Length==values+2&&int.TryParse(p[0],out node)&&int.TryParse(p[1],out load)){offset=2;lastNode=node;}
   else if(p.Length==values+1&&lastNode>0&&int.TryParse(p[0],out load)){node=lastNode;offset=1;}
   else continue;
   if(node<=0||load<=0)throw new Exception("Invalid node/load number in the ANL displacement table.");
   int cx=columns!=null?columns[0]:0,cy=columns!=null?columns[1]:1,cz=columns!=null?columns[2]:values==6?2:-1;
   AddDisplacement(data,new BeamDisplacement{Node=node,Case=load.ToString(CultureInfo.InvariantCulture),X=Number(p[offset+cx])*factor,Y=Number(p[offset+cy])*factor,Z=cz<0?0:Number(p[offset+cz])*factor});count++;
  }
  if(count==0)throw new Exception("No JOINT DISPLACEMENT table was found in the ANL file. Add PRINT JOINT DISPLACEMENTS to the STAAD input, re-run the analysis, or paste the Node Displacements table.");
  data.DisplacementUnitSource=source;
 }
}
}
